import java.util.Scanner;

public class Main {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);

    String s = sc.nextLine();

    System.out.println(getResult(s));
  }

  public static int getResult(String s) {
    int l = 0;
    int r = 0;
    int maxLen = 0;

    while (r < s.length()) {
      char c = s.charAt(r);
      if (c >= '0' && c <= '9') {
        if (l != r) {
          if (c >= s.charAt(r - 1)) {
            maxLen = Math.max(maxLen, r - l + 1);
          } else {
            maxLen = Math.max(maxLen, r - l);
            l = r;
          }
          r++;
        } else {
          maxLen = Math.max(maxLen, 1);
          r++;
        }
      } else {
        maxLen = Math.max(maxLen, r - l);
        r++;
        l = r;
      }
    }

    return maxLen;
  }
}

import java.util.Scanner;

public class Main {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);

    String s = sc.nextLine();

    System.out.println(getResult(s));
  }

  public static int getResult(String s) {
    int maxNum = 0;
    int len = 0;
    int maxLen = 0;

    for (int i = 0; i < s.length(); i++) {
      char c = s.charAt(i);

      if (c >= '0' && c <= '9') {
        int curNum = c - '0';

        if (len == 0) {
          len = 1;
          maxNum = curNum;
        } else {
          if (curNum >= maxNum) {
            len++;
          } else {
            len = 1;
          }
          maxNum = curNum;
        }
      } else {
        len = 0;
        maxNum = 0;
      }

      maxLen = Math.max(maxLen, len);
    }

    return maxLen;
  }
}

