function getMaxLen(str) {
  let L = 0;
  let R = 0;
  let maxLen = 0;

  while (R < str.length) {
    if (/\d/.test(str[R])) {
      if (L !== R) {
        if (str[R] - 0 >= str[R - 1] - 0) {
          maxLen = Math.max(maxLen, R - L + 1);
          R++;
        } else {
          maxLen = Math.max(maxLen, R - L);
          L = R;
          R++;
        }
      } else {
        maxLen = Math.max(maxLen, 1);
        R++;
      }
    } else {
      maxLen = Math.max(maxLen, R - L);
      R++;
      L = R;
    }
  }

  return maxLen;
}

