  let len = 0;
  let maxNum = 0;

  for (let i = 0; i < str.length; i++) {
    if (/\d/.test(str[i])) {
      let curNum = str[i] - 0;
      if (len === 0) {
        len = 1;
        maxNum = curNum;
      } else {
        curNum >= maxNum ? len++ : (len = 1);
        maxNum = curNum;
      }
    } else {
      len = 0;
      maxNum = 0;
    }

    maxLen = Math.max(maxLen, len);
  }

  return maxLen;
}

