#include <string.h>

#define MAX(a,b) a > b ? a : b

int main() {
    char s[255];
    scanf("%s", s);

    int l = 0;
    int r = 0;
    int maxLen = 0;

    while(r < strlen(s)) {
        char c = s[r];

        if(c >= '0' && c <= '9') {
            if(l != r) {
                if(c >= s[r - 1]) {
                    maxLen = MAX(maxLen, r - l + 1);
                } else {
                    maxLen = MAX(maxLen, r - l);
                    l = r;
                }
                r++;
            } else {
                maxLen = MAX(maxLen, 1);
                r++;
            }
        } else {
            maxLen = MAX(maxLen, r - l);
            r++;
            l = r;
        }
    }

    printf("%d\n", maxLen);

